            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Das Leben der Vornehmen ist ein langer Sonntag, [...]. Das Leben des Bauern ist ein langer Werktag;", Author = "Georg Büchner" },
