            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Das Verbrechen hat kein Asyl, nur gekrönte Verbrechen finden eins auf dem Thron.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Die allgemeinen fixen Ideen, welche man die gesunde Vernunft tauft, sind unerträglich langweilig.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Einander kennen? Wir müßten uns die Schädeldecken aufbrechen und die Gedanken einander aus den Hirnfasern zerren.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Es haßt die Genießenden, wie ein Eunuch die Männer.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Das Leben ist nicht der Arbeit werth, die man sich macht, es zu erhalten.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Das Volk ist ein Minotaurus, der wöchentlich seine Leichen haben muß, wenn er sie nicht auffressen soll.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Der Tod äfft die Geburt; bei’m Sterben sind wir so hülflos und nackt, wie neugeborne Kinder.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Die Revolution ist wie Saturn, sie frißt ihre eigenen Kinder.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Die Schritte der Menschheit sind langsam, man kann sie nur nach Jahrhunderten zählen, hinter jedem erheben sich die Gräber von Generationen.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Die Statue der Freiheit ist noch nicht gegossen, der Ofen glüht, wir Alle können uns noch die Finger dabei verbrennen.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Die Unterdrücker der Menschheit bestrafen ist Gnade, ihnen verzeihen ist Barbarei.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Für das Volk sind Schwäche und Mäßigung eins; es schlägt die Nachzügler todt.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Geht einmal Euern Phrasen nach, bis zu dem Punkt, wo sie verkörpert werden.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Was ist’s denn, wenn ich auf eine Leiche trete, um aus dem Grab zu klettern?", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Wer in einer Masse, die vorwärts drängt, stehen bleibt, leistet so gut Widerstand, als trät’ er ihr entgegen, er wird zertreten.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Wir haben nicht die Revolution, die Revolution hat uns gemacht.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Wir sind das Volk, und wir wollen, daß kein Gesetz sei; ergo: ist dieser Wille das Gesetz, ergo: im Namen des Gesetzes gibt's kein Gesetz mehr, ergo: todtgeschlagen.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Wir sind Dickhäuter, wir strecken die Hände nach einander aus; aber es ist vergebliche Mühe, wir reiben nur das grobe Leder an einander ab, — wir sind sehr einsam.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Wo die Nothwehr aufhört, fängt der Mord an; ich sehe keinen Grund, der uns länger zum Tödten zwänge.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Wozu sollen wir Menschen mit einander kämpfen? Wir sollten uns neben einander setzen und Ruhe haben.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Der müde Leib findet sein Schlafkissen überall, doch wenn der Geist müd' ist, wo soll er ruh’n?", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Für müde Füße ist jeder Weg zu lang ...", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Ich bin so jung, und die Welt ist so alt.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Mein Leben gähnt mich an, wie ein großer weißer Bogen Papier, den ich vollschreiben soll, aber ich bringe keinen Buchstaben heraus.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Müßiggang ist aller Laster Anfang.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "O Himmel, man kömmt leichter zu seiner Erzeugung, als zu seiner Erziehung.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "O, eine sterbende Liebe ist schöner als eine werdende.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Denn wer arbeitet, ist ein subtiler Selbstmörder, und ein Selbstmörder ist ein Verbrecher, und ein Verbrecher ist ein Schuft. Also, wer arbeitet ist ein Schuft.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Ich werde mich indessen in das Gras legen und meine Nase oben zwischen den Halmen herausblühen lassen und romantische Empfindungen beziehen, wenn die Bienen und Schmetterlinge sich darauf wiegen, wie auf einer Rose.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Auf der Welt ist kein Bestand, // Wir müssen Alle sterben, das ist uns wohlbekannt. // Heissassa! Hopssassa!", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Es muß was Schönes sein um die Tugend, Herr Hauptmann, aber ich bin ein armer Kerl.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Es wird mir ganz angst um die Welt, wenn ich an die Ewigkeit denke.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Ich ärger mich nicht, ärgern ist ungesund, ist unwissenschaftlich!", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Der Mensch ist ein Abgrund, es schwindelt Einem, wenn man hinunterschaut ...", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Moral, das ist, wenn man moralisch ist [...]", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Wer kalt ist, den friert nicht mehr!", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Wozzeck, es schaudert mich, wenn ich denke, daß sich die Welt in einem Tage herumdreht. Was für eine Zeitverschwendung! - wo soll das hinaus? So geschwind geht Alles! - Wozzeck, ich kann kein Mühlrad mehr sehen, oder ich werd’ melancholisch!", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Der Hass ist so gut erlaubt als die Liebe, und ich hege ihn im vollsten Maße gegen die, ''welche verachten''.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Die Leute gehen ins Feuer, wenn's von einer brennenden Punschbowle kommt!", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Gott mag den allerdurchlauchtigsten und gesalbten Schafsköpfen gnädig sein; auf der Erde werden sie hoffentlich keine Gnade mehr finden.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Mästen Sie die Bauern, und die Revolution bekommt die Apoplexie. Ein ''Huhn'' im Topfe jedes Bauern macht den gallischen ''Hahn'' verenden.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Was ist das, was in uns lügt, mordet, stiehlt?", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Weil wir im Kerker geboren und großgezogen sind, merken wir nicht mehr, daß wir im Loch stecken mit angeschmiedeten Händen und Füßen und einem Knebel im Munde.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Wenn in unserer Zeit etwas helfen soll, so ist es Gewalt. Wir wissen, was wir von unseren Fürsten zu erwarten haben.", Author = "Georg Büchner" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Büchner", Text = "Wer will dem Adler die Bahn vorschreiben, wenn er die Schwingen entfaltet und stürmischen Flugs sich zu den Sternen erhebt?", Author = "Georg Büchner" },
